const KEYWORDS = ['async remote','asynchronous remote','worldwide remote','global remote',
  'work from anywhere','remote ai agent','remote ai agent engineer','remote ai agent developer',
  'ai agent','ai agent engineer','ai agent developer','agentic ai','agent engineer',
  'llm agent','multi-agent','multi agent','autonomous agent','ai automation engineer',
  'ai automation specialist','ai workflow consultant','ai workflow engineer',
  'conversational ai','rag engineer','prompt engineer','chatbot engineer','chatbot developer',
  'applied ai engineer','ai product engineer','langchain','crewai','autogen','n8n developer'];
const out = [];
for (const item of items) {
  const j = item.json;
  const hay = [j.job_title, j.description, j.tags].filter(Boolean).join(' ').toLowerCase();
  if (!hay.trim()) continue;
  if (KEYWORDS.some(k => hay.includes(k))) out.push(item);
}
return out;

const existingUrls = items.map(i => (i.json.job_url || '').trim()).filter(Boolean);
const existingKeys = items.map(i => ((i.json.company || '') + '|' + (i.json.job_title || '')).toLowerCase().trim()).filter(k => k !== '|');
return [{ json: { __marker: 'existingUrls', existingUrls, existingKeys } }];

const marker = items.find(i => i.json.__marker === 'existingUrls');
const existingUrls = new Set((marker ? marker.json.existingUrls : []) || []);
const existingKeys = new Set((marker ? marker.json.existingKeys : []) || []);
const jobs = items.filter(i => i.json.__marker !== 'existingUrls');
const seenUrls = new Set();
const seenKeys = new Set();
const out = [];
for (const item of jobs) {
  const j = item.json;
  const url = (j.job_url || '').trim();
  const key = ((j.company || '') + '|' + (j.job_title || '')).toLowerCase().trim();
  if (!url && key === '|') continue;
  if (url && existingUrls.has(url)) continue;
  if (!url && existingKeys.has(key)) continue;
  if (url && seenUrls.has(url)) continue;
  if (!url && seenKeys.has(key)) continue;
  seenUrls.add(url); seenKeys.add(key);
  out.push({ json: { ...j, job_id: url || key, date_found: new Date().toISOString().slice(0, 10) } });
}
return out;

const REJECT_RULES = [
  { cat: 'us_only', patterns: ['us only', 'u.s. only', 'united states only', 'usa only'] },
  { cat: 'canada_only', patterns: ['canada only'] },
  { cat: 'uk_only', patterns: ['uk only', 'u.k. only', 'united kingdom only'] },
  { cat: 'eu_only', patterns: ['eu only', 'europe only', 'european union only'] },
  { cat: 'australia_only', patterns: ['australia only', 'au only'] },
  { cat: 'must_live_authorized', patterns: ['must be based in', 'must live in', 'must be authorized to work in', 'local work permit required', 'remote within country only'] },
  { cat: 'hybrid_onsite', patterns: ['hybrid', 'onsite', 'on-site', 'office required'] },
  { cat: 'timezone_hardfilter', patterns: ['fixed us hours', 'fixed eu hours'] },
];
const KEEP_SIGNALS = ['worldwide remote', 'global remote', 'work from anywhere', 'anywhere',
  'apac remote', 'international contractors', 'contractor role', 'b2b contractor',
  'hires via deel', 'hires via remote.com', 'hires via oyster', 'eor supported',
  'remote first', 'distributed team'];
// Freshness rule: only recommend jobs posted within the current calendar month.
// Unknown/unparseable posted_date is NOT rejected (can't verify, don't punish it).
function isStalePosting(dateStr) {
  if (!dateStr) return false;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return false;
  const now = new Date();
  return !(d.getUTCFullYear() === now.getUTCFullYear() && d.getUTCMonth() === now.getUTCMonth());
}
const out = [];
for (const item of items) {
  const j = item.json;
  const hay = [j.job_title, j.description, j.location_text, j.tags].filter(Boolean).join(' ').toLowerCase();
  let rejectCat = null, rejectPhrase = null;
  if (isStalePosting(j.posted_date)) {
    rejectCat = 'stale_posting';
    rejectPhrase = 'posted_date (' + j.posted_date + ') is not within the current calendar month';
  } else {
    for (const rule of REJECT_RULES) {
      const hit = rule.patterns.find(p => hay.includes(p));
      if (hit) { rejectCat = rule.cat; rejectPhrase = hit; break; }
    }
  }
  const keepHits = KEEP_SIGNALS.filter(k => hay.includes(k));
  const stage_status = rejectCat ? 'rejected' : 'kept';
  out.push({ json: { ...j, stage_status, reject_category: rejectCat, reject_reason: rejectPhrase ? ('matched restrictive phrase: "' + rejectPhrase + '"') : null, keep_signals: keepHits.join(', ') } });
}
return out;

