let parsed = { taiwan_eligible: 'unclear', reason: 'AI parse failed', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
try {
  const text = (item.json.content && item.json.content[0] && item.json.content[0].text) || '{}';
  const cleaned = text.replace(/```json|```/g, '').trim();
  parsed = { ...parsed, ...JSON.parse(cleaned) };
} catch (e) { /* keep fallback */ }
return { json: { ...$('IF - Hard Filter Passed').item.json, ...parsed } };

const j = item.json;
const hay = [j.job_title, j.description, j.tags].filter(Boolean).join(' ').toLowerCase();
const HARD_REJECT = ['strict 9 to 5', 'strict 9-5', 'fixed us hours', 'fixed est hours', 'fixed pst hours',
  'fixed cet hours', 'daily live calls required', 'must overlap full business day'];
const rejectHit = HARD_REJECT.find(p => hay.includes(p));
let async_level = 'low';
if (hay.includes('async') || hay.includes('asynchronous')) async_level = 'high';
else if (hay.includes('flexible hours') || hay.includes('flexible schedule')) async_level = 'medium';
else if (hay.includes('distributed team') || hay.includes('remote first') || hay.includes('remote-first')) async_level = 'medium';
else if (hay.includes('low meeting culture') || hay.includes('work across time zones')) async_level = 'medium';
const stage_status = rejectHit ? 'rejected' : 'kept';
return { json: { ...j, async_level, stage_status, reject_category: rejectHit ? 'timezone_risk' : j.reject_category, reject_reason: rejectHit ? ('matched: "' + rejectHit + '"') : j.reject_reason } };

const j = item.json;
const hay = [j.job_title, j.description, j.tags].filter(Boolean).join(' ').toLowerCase();

// Role fit -- focused on the AI Agent field
const CORE_ROLES = ['ai agent engineer','ai agent developer','agentic ai engineer','agentic ai developer',
  'llm agent engineer','llm agent developer','multi-agent systems engineer','multi agent systems engineer',
  'autonomous agent developer','ai automation engineer','ai automation specialist','ai workflow consultant',
  'ai workflow engineer','conversational ai engineer','applied ai engineer','ai product engineer',
  'prompt engineer','rag engineer','chatbot developer','chatbot engineer'];
const ADJACENT_ROLES = ['agent','automation','ai ','llm','chatbot','workflow','prompt','langchain','crewai','autogen'];
let role_category = null, roleScore = 0;
const coreHit = CORE_ROLES.find(r => hay.includes(r));
if (coreHit) { role_category = coreHit; roleScore = 25; }
else if (ADJACENT_ROLES.some(r => hay.includes(r))) { role_category = 'adjacent role'; roleScore = 15; }
else { role_category = 'other'; roleScore = 0; }

// Taiwan eligibility score
const keepSignals = (j.keep_signals || '').toLowerCase();
let taiwanScore = 0;
if (j.taiwan_eligible === 'yes' && (keepSignals.includes('worldwide') || keepSignals.includes('anywhere') || keepSignals.includes('global') || keepSignals.includes('contractor') || keepSignals.includes('eor') || keepSignals.includes('deel') || keepSignals.includes('oyster') || keepSignals.includes('remote.com'))) taiwanScore = 40;
else if (j.taiwan_eligible === 'yes' && keepSignals.includes('apac')) taiwanScore = 30;
else if (j.taiwan_eligible === 'unclear' && !j.reject_category) taiwanScore = 20;
else if (j.taiwan_eligible === 'yes') taiwanScore = 30;
else taiwanScore = 0;

// Async fit score (best matching tier)
let asyncScore = 0;
if (j.async_level === 'high') asyncScore = 25;
else if (hay.includes('flexible hours') || hay.includes('flexible schedule')) asyncScore = 20;
else if (hay.includes('distributed team')) asyncScore = 15;
else if (hay.includes('remote first') || hay.includes('remote-first')) asyncScore = 10;

// Salary fit score
function parseMonthlyUsd(s) {
  if (!s) return null;
  const nums = String(s).replace(/,/g, '').match(/\d+(\.\d+)?/g);
  if (!nums) return null;
  let val = Math.max(...nums.map(Number));
  if (val > 20000) val = val / 12; // looks annual, convert to monthly
  return val;
}
const monthly = parseMonthlyUsd(j.salary);
let salaryScore = 0;
if (j.salary) salaryScore = 10;
if (monthly && monthly >= 3000) salaryScore = 15;
if (monthly && monthly >= 5000) salaryScore = 25;

const score = Math.min(100, taiwanScore + asyncScore + roleScore + salaryScore);

const location_risk = j.location_risk || (j.reject_category ? 'high' : 'low');
const timezone_risk = j.timezone_risk || (j.async_level === 'high' ? 'low' : (j.async_level === 'medium' ? 'medium' : 'high'));

let decision = 'reject';
if (j.taiwan_eligible === 'no' || location_risk === 'high' || timezone_risk === 'high' || score < 70) {
  decision = 'reject';
} else if (j.taiwan_eligible === 'yes' && score >= 85 && (j.async_level === 'high' || j.async_level === 'medium') && location_risk === 'low' && (timezone_risk === 'low' || timezone_risk === 'medium')) {
  decision = 'apply_immediately';
} else if (j.taiwan_eligible === 'unclear' && score >= 85 && location_risk === 'medium') {
  decision = 'manual_check';
} else if (score >= 70) {
  decision = 'keep_review';
}

const application_status = decision === 'apply_immediately' ? 'Ready to Apply'
  : decision === 'manual_check' ? 'Manual Review'
  : decision === 'keep_review' ? 'Needs Review' : 'Not Pursuing';

const why_good_fit = `${role_category} match, Taiwan eligibility ${j.taiwan_eligible} (${j.reason || 'n/a'}), async level ${j.async_level}, salary ${j.salary || 'not listed'}`;

return { json: { ...j, role_category, score, taiwanScore, asyncScore, roleScore, salaryScore, location_risk, timezone_risk, decision, application_status, why_good_fit } };

