const filteredItem = items.find(i => i.json.filtered) || { json: { filtered: [] } };
const rejectedItem = items.find(i => i.json.rejected) || { json: { rejected: [] } };
const filtered = (filteredItem.json.filtered || []).map(i => i.json || i);
const rejected = (rejectedItem.json.rejected || []).map(i => i.json || i);

const top = [...filtered].sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, 10);
const manualCheck = filtered.filter(j => j.decision === 'manual_check');

function countReject(cat) { return rejected.filter(r => (r.reason || '').startsWith(cat)).length; }
const usOnly = countReject('us_only');
const euOnly = countReject('eu_only');
const hybrid = countReject('hybrid_onsite');
const timezoneRisk = rejected.filter(r => (r.reason || '').includes('timezone_risk')).length;
const stalePosting = countReject('stale_posting');

let msg = 'Daily Taiwan Eligible Async Remote Jobs\n\nTop jobs today:\n\n';
top.forEach((j, idx) => {
  msg += `${idx + 1}. ${j.job_title}\n`;
  msg += `Company: ${j.company}\n`;
  msg += `Score: ${j.score}\n`;
  msg += `Taiwan eligible: ${j.taiwan_eligible}\n`;
  msg += `Reason: ${j.reason}\n`;
  msg += `Async level: ${j.async_level}\n`;
  msg += `Timezone risk: ${j.timezone_risk}\n`;
  msg += `Salary: ${j.salary || 'not listed'}\n`;
  msg += `Why it fits Jerry: ${j.why_good_fit}\n`;
  msg += `Apply link: ${j.job_url}\n\n`;
});

msg += 'Manual check:\n';
if (manualCheck.length === 0) msg += 'None today.\n';
else manualCheck.forEach(j => { msg += `- ${j.job_title} @ ${j.company} (score ${j.score}) - ${j.job_url}\n`; });

msg += '\nRejected summary:\n';
msg += `US only: ${usOnly}\n`;
msg += `EU only: ${euOnly}\n`;
msg += `Hybrid: ${hybrid}\n`;
msg += `Timezone risk: ${timezoneRisk}\n`;
msg += `Stale posting (not this month): ${stalePosting}\n`;
msg += `Total rejected: ${rejected.length}\n`;

return [{ json: { digest_text: msg, top_count: top.length, rejected_count: rejected.length, manual_check_count: manualCheck.length } }];
